import osfrom openai import OpenAI, APIStatusErrorfrom tools import get_schemas, executeimport jsonfrom permissions import PermissionManagerfrom context import compact, clear_old_tool_results, truncate_tool_result, load_session, save_sessionclient = OpenAI(    base_url=os.getenv("BASE_URL", "https://api.deepseek.com"),    api_key=os.getenv("API_KEY"))SYSTEM = (    "你是一个能操作本地文件和命令行的编程助手。"    "需要时调用工具，完成任务后直接用文字总结，不要再调用工具。")MAX_STEPS = 20MODEL_NAME = "deepseek-flash"HARD_LIMIT = 15000SOFT_LIMIT = 10000usage = {"prompt_tokens": 0}def run(user_input: str, messages: list, perms: PermissionManager) -> str:    messages.append({"role": "user", "content": user_input})    for step in range(1, MAX_STEPS + 1):        try:            if usage["prompt_tokens"] > HARD_LIMIT:                print(f"    [正在压缩上下文，当前prompt_tokens={usage['prompt_tokens']}]")                messages[:] = compact(client, MODEL_NAME, messages)            elif usage["prompt_tokens"] > SOFT_LIMIT:                print(f"    [正在清理旧的工具结果，当前prompt_tokens={usage['prompt_tokens']}]")                messages = clear_old_tool_results(messages)                        resp = client.chat.completions.create(                model=MODEL_NAME,                messages=messages,                tools=get_schemas()            )        except APIStatusError as e:            print("请求地址：", e.response.request.url)            print("状态码：", e.status_code)            print("响应内容：", e.response.text)            raise        prompt_tokens = resp.usage.prompt_tokens if resp.usage else 0        usage["prompt_tokens"] = prompt_tokens        print(f"  [prompt_tokens={usage['prompt_tokens']}]")        msg = resp.choices[0].message        messages.append(msg.model_dump(exclude_none=True))                # 模型没有调用工具 = 它认为任务已经做完了，即本次task结束        if not msg.tool_calls:            return f"\n[完成，共{step}步]\n {msg.content}"                 # 模型调用tool，需要把tool_result喂回去        for call in msg.tool_calls:            result = handle_call(call, perms)            messages.append({"role": "tool", "tool_call_id": call.id, "content": truncate_tool_result(result)})        return f"\n[达到{MAX_STEPS}步上限，已停止]"def handle_call(call, perms: PermissionManager):    name = call.function.name    try:        args = json.loads(call.function.arguments or "{}")    except json.JSONDecodeError:        return "Error: 参数不是合法的JSON"    except Exception as e:  # 错误信息fallback给模型修正       return f"工具执行出错：{type(e).__name__}:{e}"    decision = perms.check(name, args)    if not decision.allowed:        return f"[权限拒绝] {decision.reason}"    else:        print(f"🔧 {name}({call.function.arguments[:80]})")        result = execute(name, args)    print(f"\n[工具调用结果: {result}]")    return resultif __name__ == "__main__":    perms = PermissionManager()    messages = load_session("default") or [{"role": "system", "content": SYSTEM}]    while True:        q = input("你:>").strip()        if q in ("exit", "quit"):            break        print("\n" + "AI Bot:>" + run(q, messages, perms) + "\n")        save_session("default", messages)         